package ai.decisionos.aside;
import android.app.job.*;import android.content.*;import android.os.*;import android.webkit.*;import org.json.*;
/** Authenticated read-only announcement polling through the shared school WebView profile. */
public final class BlackboardNoticeMonitor extends JobService {
 static final int JOB=90601,NOW=90602;WebView web;JobParameters running;final Handler h=new Handler(Looper.getMainLooper());int generation;
 static boolean schedule(Context c,boolean now){try{JobInfo.Builder b=new JobInfo.Builder(now?NOW:JOB,new ComponentName(c,BlackboardNoticeMonitor.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY);if(now)b.setOverrideDeadline(10000);else b.setPersisted(true).setPeriodic(6L*60*60*1000);boolean ok=((JobScheduler)c.getSystemService(JOB_SCHEDULER_SERVICE)).schedule(b.build())==JobScheduler.RESULT_SUCCESS;if(!now)c.getSharedPreferences("nubi_blackboard_monitor",0).edit().putBoolean("enabled",ok).apply();return ok;}catch(Exception e){return false;}}
 static void stop(Context c){JobScheduler s=(JobScheduler)c.getSystemService(JOB_SCHEDULER_SERVICE);s.cancel(JOB);s.cancel(NOW);c.getSharedPreferences("nubi_blackboard_monitor",0).edit().putBoolean("enabled",false).apply();}
 public boolean onStartJob(JobParameters p){running=p;int gen=++generation;h.post(()->{web=new WebView(this);WebSessionPolicy.attach(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient(){boolean queued;public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return r.isForMainFrame()&&!SchoolSignIn.allowed(r.getUrl().toString());}public void onPageFinished(WebView v,String url){WebSessionPolicy.checkpoint();if(gen!=generation)return;if(url.startsWith("https://blackboard.unist.ac.kr/ultra/institution-page")){v.loadUrl("https://blackboard.unist.ac.kr/ultra/course");return;}if(url.startsWith("https://blackboard.unist.ac.kr/ultra/")&&!queued){queued=true;h.postDelayed(()->read(gen),10000);}else if(url.startsWith("https://blackboard.unist.ac.kr/"))v.evaluateJavascript("(()=>{const b=document.getElementById('unist-portal-login');if(b)b.click()})()",r->{});}});h.postDelayed(()->finish(gen,"시간 초과 · Blackboard 연결 확인 필요",true),90000);web.loadUrl("https://blackboard.unist.ac.kr/ultra/course");});return true;}
 void read(int gen){if(gen!=generation||web==null)return;try{String script;try(java.io.InputStream in=getAssets().open("blackboard_tools.js")){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)bytes.write(buf,0,n);script=new String(bytes.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}web.evaluateJavascript(script+";NubiBBTools.run({mode:'notices'}).then(r=>window.__nubiNoticeResult=JSON.stringify(r)).catch(e=>window.__nubiNoticeResult=JSON.stringify({state:'failed'}));",r->poll(gen,0));}catch(Exception e){finish(gen,"Blackboard 조회 도구를 열지 못했어요",true);}}
 void poll(int gen,int count){if(gen!=generation||web==null)return;if(count>60){finish(gen,"Blackboard 공지 응답 시간 초과",true);return;}web.evaluateJavascript("window.__nubiNoticeResult||null",raw->{if(gen!=generation)return;if(raw==null||raw.equals("null")){h.postDelayed(()->poll(gen,count+1),1000);return;}try{JSONObject r=new JSONObject(new JSONArray("["+raw+"]").getString(0));if(!r.optString("state").equals("observed")){finish(gen,"Blackboard 공지 미확인 · 로그인 또는 강의 목록 확인 필요",true);return;}int added=store(this,r.optJSONArray("items"));boolean baseline=getSharedPreferences("nubi_blackboard_monitor",0).getBoolean("announcement_api_baseline",false);getSharedPreferences("nubi_blackboard_monitor",0).edit().putBoolean("announcement_api_baseline",true).apply();if(baseline&&added>0)CampusNoticeMonitor.notifyChanges(this,added,"Blackboard에 새 공지나 변경된 안내가 있어요. 게시일과 원문을 확인해 주세요.");finish(gen,"공지 조회 · "+r.optJSONArray("items").length()+"건 · 새 항목/변경 "+added+(r.optBoolean("partial")?" · 일부 범위만 확인":""),false);}catch(Exception e){finish(gen,"Blackboard 공지 응답을 읽지 못했어요",true);}});}
 static int store(Context c,JSONArray rows){if(rows==null)return 0;int count=0;try(CampusFlowStore s=new CampusFlowStore(c)){for(int n=0;n<rows.length();n++){JSONObject row=rows.optJSONObject(n);if(row==null||row.optString("id").isEmpty())continue;String source="bb-notice:"+row.optString("courseId")+":"+row.optString("id"),title=row.optString("title"),text=row.optString("text");JSONObject old=s.get(source);if(old.has("id")&&old.optString("text").equals(text)&&old.optString("title").equals(title))continue;try{JSONObject saved=new JSONObject(row.toString());GoalStore.put(saved,"id",source);GoalStore.put(saved,"service","blackboard");GoalStore.put(saved,"category",CampusWorkflows.category(title));s.save("observations",saved);SchoolChatWork.publish(c,"blackboard",source,title,text,row.optString("url"),row.optString("createdAt"));count++;}catch(Exception ignored){}}}return count;}
 void finish(int gen,String status,boolean retry){if(gen!=generation)return;generation++;getSharedPreferences("nubi_blackboard_monitor",0).edit().putString("status",status).putLong("checked",System.currentTimeMillis()).apply();h.removeCallbacksAndMessages(null);if(web!=null){web.stopLoading();web.destroy();web=null;}if(running!=null){jobFinished(running,retry);running=null;}}
 public boolean onStopJob(JobParameters p){generation++;h.removeCallbacksAndMessages(null);if(web!=null){web.destroy();web=null;}running=null;return true;}
}
